# Let's try a greedy approach to build a maximal triangle-free graph
n = 20
fixed_edges = [(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)]

# Start with fixed edges
edges = set()
for (u,v) in fixed_edges:
    edges.add((min(u,v), max(u,v)))

# Check for triangles in fixed edges
def has_triangle(edges, n):
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (i,j) in edges and (i,k) in edges and (j,k) in edges:
                    return True
    return False

print("Fixed edges have triangles:", has_triangle(edges, n))

# Greedy: try to add edges one by one
# Order matters, so let's try different orderings
import random

def try_greedy(edges, n, order):
    current_edges = set(edges)
    for (u,v) in order:
        if (u,v) in current_edges:
            continue
        # Check if adding (u,v) creates a triangle
        creates_triangle = False
        for w in range(n):
            if w != u and w != v:
                e1 = (min(u,w), max(u,w))
                e2 = (min(v,w), max(v,w))
                if e1 in current_edges and e2 in current_edges:
                    creates_triangle = True
                    break
        if not creates_triangle:
            current_edges.add((u,v))
    return current_edges

# Generate all possible edges
all_edges = []
for u in range(n):
    for v in range(u+1, n):
        all_edges.append((u,v))

# Try multiple random orderings
best_edges = None
for trial in range(1000):
    random.shuffle(all_edges)
    # Make sure fixed edges come first
    fixed_set = set((min(u,v), max(u,v)) for u,v in fixed_edges)
    ordered = [e for e in all_edges if e in fixed_set] + [e for e in all_edges if e not in fixed_set]
    result = try_greedy(edges, n, ordered)
    if best_edges is None or len(result) > len(best_edges):
        best_edges = result

print(f"Best greedy solution: {len(best_edges)} edges")

